"use client";
import "./projects.css";
import PDFViewer from "../components/pdfViewer";
import { useState, useRef, useEffect } from "react";
import { motion as m } from "motion/react";
import Image from "next/image";
import { Link } from "next/link";
import { AnimatePresence } from "motion/react";


export default function Projects() {
  const classes = [
    { label: "Senior Design", href: "/projects/seniordesign" },
    { label: "Undergraduate Research", href: "/projects/undergraduateresearch" },
    { label: "Engineering Computing", href: "/projects/engineeringcomputing" },
    { label: "Personal Projects", href: "/projects/personalprojects" },
    { label: "Experimental Aerodynamics", href: "/projects/experimentalaerodynamics" },
    { label: "Gas Turbines & Propulsions", href: "/projects/gasturbines" },
    { label: "Design Tools II", href: "/projects/designtools2" },
  ];

  const classSelectRef = useRef(null);


  const buttonVariants = {
    initial: {
      background: "var(--foreground)",
      color: "var(--copy)",
      scale: 1,
      borderRadius: "var(--border-radius)"
    },
    hovered: {
      background: "var(--primary-light)",
      color: "var(--foreground)",
      scale: 1.05,
      borderRadius: "var(--border-radius)"
    },
    tapped: {
      scale: 0.95
    }
  };

  return (
    <AnimatePresence mode="popLayout">
      <m.div
        key="project-page-key"
        className="page"
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        exit={{ opacity: 0, y: 10 }}
        transition={{ duration: 0.5, type: "spring", stiffness: 100, damping: 20 }}
      >
        <div className="projects">
          <div className="projects-header">
            <h2 className="ac-header">Academic Projects</h2>
            <div
              ref={classSelectRef}
              className="class-select-container"
              variants={buttonVariants}
              initial="initial"
              transition={{ duration: 0.5 }}
            >
              <Link key={classes.href} href={classes.href} passHref>
                <m.button
                  variants={buttonVariants}
                  initial="initial"
                  whileHover="hovered"
                  whileTap="tapped"
                  className="proj-button"
                  transition={{ duration: 0.2, ease: "easeOut" }}
                >{classes.label}
                </m.button>
              </Link>

            </div>
          </div>
        </div>
      </m.div>
    </AnimatePresence>
  )
}
